git diff --stat data/verification/page-345.json && python3 - <<'EOF'
import json,subprocess
new=json.load(open('data/verification/page-345.json',encoding='utf-8'))
old=json.loads(subprocess.check_output(['git','show','HEAD:data/verification/page-345.json']).decode())
def strip(o):
    import copy
    o=copy.deepcopy(o)
    for e in o['entries']:
        e.pop('consulted',None)
        for it in e.get('ref_check',[]): it.pop('status',None); it.pop('note',None)
        for n in e['nodes']:
            n.pop('consulted',None)
            for it in n.get('ref_check',[]): it.pop('status',None); it.pop('note',None)
    return o
print('non-consulted/ref_check fields identical:', strip(new)==strip(old))
# list ref_check status changes
for eo,en in zip(old['entries'],new['entries']):
    for a,b in zip(eo.get('ref_check',[]),en.get('ref_check',[])):
        if a['status']!=b['status']: print('ROOT',eo['entry'],a['ref'],a['status'],'->',b['status'])
    for no,nn in zip(eo['nodes'],en['nodes']):
        for a,b in zip(no.get('ref_check',[]),nn.get('ref_check',[])):
            if a['status']!=b['status']: print('node',eo['entry'],no['id'],a['ref'],a['status'],'->',b['status'])
EOF
